    issueDate: '2025-01-15',
    status: 'cancelled',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice preserves all invoice fields', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-12-25',
    lines: [
